1	import React, { useState, useMemo } from 'react';
2	import { getCaixaDetalhe } from '../../services/restauranteService';
3	import Icon from '../../components/AppIcon';
4	
5	const fmt    = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
6	const fmtDt  = (d) => d ? new Date(d).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
7	const isoDay = (d) => new Date(d).toISOString().slice(0, 10);
8	const isoMon = (d) => new Date(d).toISOString().slice(0, 7);
9	const today     = () => new Date().toISOString().slice(0, 10);
10	const thisMonth = () => new Date().toISOString().slice(0, 7);
11	
12	const STATUS_BADGE  = { aberto: 'bg-green-100 text-green-700 border border-green-200', fechado: 'bg-gray-100 text-gray-600 border border-gray-200', expirado: 'bg-red-100 text-red-700 border border-red-200' };
13	const STATUS_BORDER = { aberto: 'border-l-green-400', fechado: 'border-l-gray-300', expirado: 'border-l-red-400' };
14	const STATUS_LABEL  = { aberto: 'Aberto', fechado: 'Fechado', expirado: 'Expirado' };
15	const MEIO_LABELS   = { dinheiro: '💵', pix: '🏦', transferencia: '🔀', cartao: '💳' };
16	
17	const KpiCard = ({ icon, label, value, accent }) => (
18	  <div className="bg-white rounded-2xl border border-[#E4E4E7] px-5 py-4 flex items-center gap-4">
19	    <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${accent ? 'bg-[#FF441F]/10' : 'bg-[#F4F4F5]'}`}>
20	      <Icon name={icon} size={18} className={accent ? 'text-[#FF441F]' : 'text-[#71717A]'} />
21	    </div>
22	    <div className="min-w-0">
23	      <p className="text-xs text-[#71717A] font-medium truncate">{label}</p>
24	      <p className={`text-lg font-black truncate ${accent ? 'text-[#FF441F]' : 'text-[#18181B]'}`}>{value}</p>
25	    </div>
26	  </div>
27	);
28	
29	const Row = ({ label, value, bold, accent }) => (
30	  <div className={`flex justify-between text-sm py-1.5 border-b border-[#F4F4F5] last:border-0 ${bold ? 'font-bold' : ''}`}>
31	    <span className="text-[#71717A]">{label}</span>
32	    <span className={accent ? 'text-[#FF441F] font-bold' : 'text-[#18181B]'}>{value}</span>
33	  </div>
34	);
35	
36	const HistoricoCaixasPanel = ({ historico = [] }) => {
37	  const [expandido,      setExpandido]      = useState(null);
38	  const [detalhe,        setDetalhe]        = useState({});
39	  const [loadingDetalhe, setLoadingDetalhe] = useState(null);
40	
41	  const [busca,  setBusca]  = useState('');
42	  const [status, setStatus] = useState('todos');
43	  const [modoDt, setModoDt] = useState('todos');
44	  const [mesSel, setMesSel] = useState(thisMonth());
45	  const [dtIni,  setDtIni]  = useState(today());
46	  const [dtFim,  setDtFim]  = useState(today());
47	
48	  const handleExpand = async (id) => {
49	    if (expandido === id) { setExpandido(null); return; }
50	    setExpandido(id);
51	    if (detalhe[id]) return;
52	    setLoadingDetalhe(id);
53	    try {
54	      const d = await getCaixaDetalhe(id);
55	      setDetalhe((prev) => ({ ...prev, [id]: d }));
56	    } catch { /* silent */ } finally { setLoadingDetalhe(null); }
57	  };
58	
59	  const filtrado = useMemo(() => {
60	    const now    = new Date();
61	    const semana = new Date(now); semana.setDate(now.getDate() - 7);
62	    return historico.filter((c) => {
63	      if (busca && !c.nome_operador.toLowerCase().includes(busca.toLowerCase())) return false;
64	      if (status !== 'todos' && c.status !== status) return false;
65	      const aberto = new Date(c.aberto_em);
66	      if (modoDt === 'hoje')    return isoDay(aberto) === today();
67	      if (modoDt === 'semana')  return aberto >= semana;
68	      if (modoDt === 'mes')     return isoMon(aberto) === thisMonth();
69	      if (modoDt === 'mes_sel') return isoMon(aberto) === mesSel;
70	      if (modoDt === 'periodo') return aberto >= new Date(dtIni) && aberto <= new Date(dtFim + 'T23:59:59');
71	      return true;
72	    });
73	  }, [historico, busca, status, modoDt, mesSel, dtIni, dtFim]);
74	
75	  const kpis = useMemo(() => {
76	    const perdas = filtrado.reduce((s, c) => { const d = c.destinacao_fechamento?.diferenca ?? 0; return s + (d < 0 ? -d : 0); }, 0);
77	    const saldo  = filtrado.reduce((s, c) => s + (c.resumo?.saldo ?? 0) + (c.destinacao_fechamento?.diferenca ?? 0), 0);
78	    return { total: filtrado.length, abertos: filtrado.filter((c) => c.status === 'aberto').length, vendas: filtrado.reduce((s, c) => s + (c.resumo?.total_vendas ?? 0), 0), saldo, perdas };
79	  }, [filtrado]);
80	
81	  return (
82	    <div className="space-y-4">
83	      {/* Título */}
84	      <div className="flex items-center justify-between">
85	        <p className="text-sm font-black text-[#18181B] uppercase tracking-widest">Histórico de Caixas</p>
86	        <p className="text-xs text-[#71717A]">{historico.length} sessões</p>
87	      </div>
88	
89	      {/* KPIs */}
90	      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
91	        <KpiCard icon="Archive"    label="Caixas"       value={kpis.total} />
92	        <KpiCard icon="Unlock"     label="Abertos"      value={kpis.abertos} />
93	        <KpiCard icon="TrendingUp" label="Total Vendas" value={fmt(kpis.vendas)} accent />
94	        <div className={`bg-white rounded-2xl border px-5 py-4 flex items-center gap-4 ${kpis.perdas > 0 ? 'border-red-200' : 'border-[#E4E4E7]'}`}>
95	          <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${kpis.perdas > 0 ? 'bg-red-50' : 'bg-[#F4F4F5]'}`}>
96	            <Icon name="Wallet" size={18} className={kpis.perdas > 0 ? 'text-red-500' : 'text-[#71717A]'} />
97	          </div>
98	          <div className="min-w-0">
99	            <p className="text-xs text-[#71717A] font-medium">Saldo Líquido Real</p>
100	            <p className={`text-lg font-black truncate ${kpis.perdas > 0 ? 'text-red-600' : 'text-[#18181B]'}`}>{fmt(kpis.saldo)}</p>
101	            {kpis.perdas > 0 && <p className="text-[10px] text-red-500 font-semibold"><Icon name="TrendingDown" size={10} className="inline" /> perdas: {fmt(kpis.perdas)}</p>}
102	          </div>
103	        </div>
104	      </div>
105	
106	      {/* Filtros */}
107	      <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 space-y-3">
108	        <p className="text-xs font-black text-[#A1A1AA] uppercase tracking-widest">Filtros</p>
109	        <div className="flex flex-col sm:flex-row gap-3">
110	          <div className="relative flex-1">
111	            <Icon name="Search" size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]" />
112	            <input type="text" value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar por operador…"
113	              className="w-full pl-9 pr-4 py-2.5 text-sm border border-[#E4E4E7] rounded-xl bg-[#FAFAFA] focus:outline-none focus:border-[#FF441F]" />
114	            {busca && <button onClick={() => setBusca('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]"><Icon name="X" size={14} /></button>}
115	          </div>
116	          <select value={status} onChange={(e) => setStatus(e.target.value)}
117	            className="mx-2 sm:mx-0 sm:w-40 px-3 py-2.5 text-sm border border-[#E4E4E7] rounded-xl bg-[#FAFAFA] focus:outline-none focus:border-[#FF441F]">
118	            <option value="todos">Todos os status</option>
119	            <option value="aberto">Aberto</option>
120	            <option value="fechado">Fechado</option>
121	            <option value="expirado">Expirado</option>
122	          </select>
123	        </div>
124	        <div className="flex flex-wrap gap-2 items-center">
125	          {[{ v: 'todos', l: 'Todos' }, { v: 'hoje', l: 'Hoje' }, { v: 'semana', l: '7 dias' }, { v: 'mes', l: 'Mês atual' }, { v: 'mes_sel', l: 'Mês' }, { v: 'periodo', l: 'Período' }].map(({ v, l }) => (
126	            <button key={v} onClick={() => setModoDt(v)}
127	              className={`px-3 py-1.5 text-xs font-semibold rounded-lg border transition-colors ${modoDt === v ? 'bg-[#FF441F] text-white border-[#FF441F]' : 'bg-[#FAFAFA] text-[#71717A] border-[#E4E4E7] hover:border-[#FF441F] hover:text-[#FF441F]'}`}>
128	              {l}
129	            </button>
130	          ))}
131	        </div>
132	        {modoDt === 'mes_sel' && <input type="month" value={mesSel} onChange={(e) => setMesSel(e.target.value)} className="mx-2 sm:mx-0 w-48 px-3 py-2 text-sm border border-[#E4E4E7] rounded-xl focus:outline-none focus:border-[#FF441F]" />}
133	        {modoDt === 'periodo' && (
134	          <div className="flex flex-wrap gap-3 items-center">
135	            <label className="text-xs text-[#71717A] font-medium">De</label>
136	            <input type="date" value={dtIni} onChange={(e) => setDtIni(e.target.value)} className="px-3 py-2 text-sm border border-[#E4E4E7] rounded-xl focus:outline-none focus:border-[#FF441F]" />
137	            <label className="text-xs text-[#71717A] font-medium">até</label>
138	            <input type="date" value={dtFim} onChange={(e) => setDtFim(e.target.value)} className="px-3 py-2 text-sm border border-[#E4E4E7] rounded-xl focus:outline-none focus:border-[#FF441F]" />
139	          </div>
140	        )}
141	        <p className="text-xs text-[#A1A1AA]">{filtrado.length === historico.length ? `${historico.length} caixas` : `${filtrado.length} de ${historico.length} caixas`}</p>
142	      </div>
143	
144	      {/* Lista */}
145	      {filtrado.length === 0 ? (
146	        <div className="bg-white rounded-2xl border border-[#E4E4E7] p-12 text-center">
147	          <Icon name="FilterX" size={32} className="text-[#D4D4D8] mx-auto mb-3" />
148	          <p className="text-[#71717A] font-medium">Nenhum caixa encontrado.</p>
149	          <button onClick={() => { setBusca(''); setStatus('todos'); setModoDt('todos'); }} className="mt-4 text-sm text-[#FF441F] font-semibold hover:underline">Limpar filtros</button>
150	        </div>
151	      ) : (
152	        <div className="space-y-3">
153	          {filtrado.map((c) => {
154	            const r      = c.resumo ?? {};
155	            const d      = c.destinacao_fechamento;
156	            const isOpen = expandido === c.id;
157	            const det    = detalhe[c.id];
158	            const temPerda = (d?.diferenca ?? 0) < 0;
159	            const border = temPerda ? 'border-l-red-400' : (STATUS_BORDER[c.status] ?? 'border-l-gray-300');
160	
161	            return (
162	              <div key={c.id} className={`bg-white rounded-2xl border border-[#E4E4E7] border-l-4 ${border} overflow-hidden`}>
163	                <button onClick={() => handleExpand(c.id)} className="w-full flex items-center gap-4 px-5 py-4 text-left hover:bg-[#FAFAFA] transition-colors">
164	                  <div className="w-9 h-9 rounded-xl bg-[#F4F4F5] flex items-center justify-center flex-shrink-0">
165	                    <Icon name="User" size={16} className="text-[#71717A]" />
166	                  </div>
167	                  <div className="flex-1 min-w-0">
168	                    <div className="flex items-center gap-2 flex-wrap">
169	                      <span className={`text-xs px-2 py-0.5 rounded-full font-semibold ${STATUS_BADGE[c.status] ?? 'bg-gray-100 text-gray-700'}`}>{STATUS_LABEL[c.status] ?? c.status}</span>
170	                      {d?.conferencia_aprovada === true  && <span className="text-xs px-2 py-0.5 rounded-full font-semibold bg-green-100 text-green-700 border border-green-200">✓ Aprovado</span>}
171	                      {d?.conferencia_aprovada === false && <span className="text-xs px-2 py-0.5 rounded-full font-semibold bg-amber-100 text-amber-700 border border-amber-200">⏳ Conf. Pendente</span>}
172	                      {temPerda && <span className="text-xs px-2 py-0.5 rounded-full font-semibold bg-red-100 text-red-700 border border-red-200"><Icon name="TrendingDown" size={10} className="inline mr-0.5" />{fmt(d.diferenca)} perda</span>}
173	                      <p className="text-sm font-bold text-[#18181B] truncate">{c.nome_operador}</p>
174	                      <p className="text-xs text-[#A1A1AA]">#{c.id}</p>
175	                    </div>
176	                    <p className="text-xs text-[#71717A] mt-0.5"><Icon name="Calendar" size={11} className="inline mr-1" />{fmtDt(c.aberto_em)}{c.fechado_em ? <> → {fmtDt(c.fechado_em)}</> : ''}</p>
177	                  </div>
178	                  <div className="text-right flex-shrink-0 mr-2">
179	                    <p className={`text-sm font-black ${temPerda ? 'text-red-600' : 'text-[#18181B]'}`}>{fmt((r.saldo ?? 0) + (d?.diferenca ?? 0))}</p>
180	                    <p className="text-xs text-[#71717A]">vendas: {fmt(r.total_vendas)}</p>
181	                    {temPerda && <p className="text-[10px] text-red-400">sistema: {fmt(r.saldo)}</p>}
182	                  </div>
183	                  <Icon name={isOpen ? 'ChevronUp' : 'ChevronDown'} size={16} className="text-[#A1A1AA] flex-shrink-0" />
184	                </button>
185	
186	                {isOpen && (
187	                  <div className="border-t border-[#F4F4F5] px-5 pb-5 pt-4">
188	                    {loadingDetalhe === c.id ? (
189	                      <div className="flex justify-center py-4"><div className="w-5 h-5 border-[3px] border-[#FF441F] border-t-transparent rounded-full animate-spin" /></div>
190	                    ) : det ? (() => {
191	                      const saidas = det.caixa.saidas ?? [];
192	                      const entradas = det.caixa.entradas ?? [];
193	                      const pedidos = det.pedidos ?? [];
194	                      const dc = det.caixa.destinacao_fechamento;
195	                      const dif = dc?.diferenca ?? 0;
196	                      const difCor = dif === 0 ? 'text-green-700' : dif < 0 ? 'text-red-600' : 'text-blue-600';
197	                      return (
198	                        <div className="grid md:grid-cols-3 gap-4">
199	                          <div>
200	                            <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-2">Resumo</p>
201	                            <div className="bg-[#FAFAFA] rounded-xl p-3">
202	                              <Row label="Valor inicial" value={fmt(det.caixa.valor_inicial)} />
203	                              <Row label="Total vendas"  value={fmt(r.total_vendas)} />
204	                              {(r.total_entradas ?? 0) > 0 && <Row label="Adições"       value={fmt(r.total_entradas)} />}
205	                              <Row label="Saídas"        value={`- ${fmt(r.total_saidas)}`} />
206	                              <Row label="Saldo"         value={fmt(r.saldo)} bold accent />
207	                            </div>
208	                            {dc?.dinheiro_contado !== undefined && (
209	                              <div className={`rounded-xl p-3 mt-2 border ${dif < 0 ? 'bg-red-50 border-red-200' : dif > 0 ? 'bg-blue-50 border-blue-200' : 'bg-green-50 border-green-200'}`}>
210	                                <p className="text-[10px] font-black uppercase tracking-widest mb-1.5 text-[#71717A]">Conferência</p>
211	                                <Row label="Operador contou" value={fmt(dc.dinheiro_contado)} />
212	                                <div className={`flex justify-between text-sm font-bold pt-1 border-t mt-1 ${dif < 0 ? 'border-red-200' : 'border-green-200'}`}>
213	                                  <span className="text-[#71717A]">Diferença</span>
